          { choice: 'observe' as const, title: `Ler ${state.rival.name}`, text: 'Você guarda a resposta e observa a rival. A competição deixa de ser só provocação: vira uma pergunta que o campo responderá mais tarde.', button: 'Observar em silêncio' },
          { choice: 'assert' as const, title: 'Fazer uma promessa', text: 'Você diz qual tipo de shinobi pretende ser. Não ganha poder por isso — ganha uma história que poderá ser cobrada.', button: 'Assumir a promessa' }
